#define EXT_EEPROM_MAGIC_ADDR 0
#define EXT_EEPROM_MAGIC_VALUE 0x55AA
#define EXT_EEPROM_CONFIG_ADDR 16       // Основные настройки
#define EXT_EEPROM_BAND_ADDR 256        // Текущий диапазон
#define EXT_EEPROM_ATT_ADDR 257         // ATT состояние
#define EXT_EEPROM_PRE_ADDR 258         // PRE состояние
#define EXT_EEPROM_STEP_ADDR 259        // Текущий шаг
