#define EXT_EEPROM_RIT_ENABLED_ADDR 402 // RIT enabled
#define EXT_EEPROM_BASE_FREQ_ADDR 404   // Базовая частота
#define EXT_EEPROM_DIAL_FREQ_ADDR 408   // Dial частота
#define EXT_EEPROM_PTT_STATE_ADDR 412   // PTT состояние
#define EXT_EEPROM_ENABLED_ADDR 414     // Флаг включения внешней EEPROM
