// ==================== ОТДЕЛЬНАЯ ШИНА I2C ДЛЯ EEPROM ====================
TwoWire eepromWire = TwoWire(1);  // Вторая шина I2C для EEPROM

// ==================== ВНУТРЕННЯЯ EEPROM НАСТРОЙКИ (только для меню) ====================
#define INT_EEPROM_SIZE 512
