volatile uint8_t current_mode = 0;  // 0 - LSB, 1 - USB

// ==================== ШАГИ НАСТРОЙКИ ЧАСТОТЫ ====================
const int steps[] = {10, 100, 1000, 10000, 100000};
const int NUM_STEPS = 5;
volatile int current_step_index = 2;
volatile int freq_step = steps[current_step_index];

// ==================== ДИАПАЗОНЫ ====================
struct Band {
  const char* name;
  long start_freq;
  uint8_t mode;
  long min_freq;
  long max_freq;
  long center_freq;
};

Band bands[] = {
  {"MW",   1413000, 1, 500000,  1750000,  1413000},
  {"160m", 1850000, 0, 1800000,  2000000,  1900000},
  {"100m", 2920000, 1, 2800000,  3200000,  3000000},
  {"80m",  3640000, 0, 3500000,  4000000,  3750000},
  {"49m",  6100000, 1, 5800000,  6200000,  6015000},
  {"40m",  7100000, 0, 7000000,  7300000,  7150000},
  {"20m",  14100000, 1, 14000000, 14400000, 14175000},
  {"15m",  21100000, 1, 21000000, 21500000, 21225000},
  {"10m",  29100000, 1, 28000000, 30000000, 29000000}
};

const int NUM_BANDS = 9;
volatile int current_band = 5;
bool is_in_band = true;
bool att_enabled = false;
bool pre_enabled = false;
volatile uint8_t ptt_active = 0;      // Флаг активной передачи
int32_t base_frq = 7100000;

// ==================== ОГРАНИЧЕНИЯ ЧАСТОТЫ ====================
#define max_frq 200000000
#define min_frq 10000

// ==================== ПАРАМЕТРЫ ЭНКОДЕРА ====================
#define vth  3
#define Racc 200
#define Rdec 500
#define MAX_Step 10000

float L = 0.0;
float inv_Tacc = Racc * 1.0e-8;
float MaxL = sqrt((MAX_Step - freq_step) / inv_Tacc);
int32_t afstp;
int16_t RE_Count = 0;

// ==================== ФЛАГИ ИЗМЕНЕНИЙ ====================
uint8_t f_fchange = 1;
uint8_t f_cchange = 1;
uint8_t f_mchange = 1;
uint8_t f_bchange = 1;
uint8_t f_schange = 1;
uint8_t f_attchange = 1;
uint8_t f_prechange = 1;
uint8_t f_carON = 1;
uint8_t f_dchange = 1;

int32_t Dial_frq;
int velocity = 0;
int velo[16];
int pt_v = 0;

TaskHandle_t H_Task = NULL;
bool task_created = false;

// ==================== КНОПКИ И ПРЕРЫВАНИЯ ====================
volatile bool mode_button_pressed = false;

#define STEP_CHANGE_DELAY 800
bool band_up_pressed = false;
bool band_down_pressed = false;
unsigned long band_up_press_start = 0;
unsigned long band_down_press_start = 0;
bool band_up_long_press_active = false;
bool band_down_long_press_active = false;

#define ATT_PRE_CHANGE_DELAY 800
bool encoder_button_pressed = false;
unsigned long encoder_button_press_start = 0;
bool encoder_button_long_press_active = false;

bool eeprom_button_pressed = false;

RotaryEncoder encoder(ENCODER_PIN_A, ENCODER_PIN_B, RotaryEncoder::LatchMode::FOUR3);
volatile int encoder_pos = 0;
int last_encoder_pos = 0;

#define BGCol TFT_BLACK

bool rit_button_pressed = false;

// ==================== ФЛАГИ ДЛЯ PTT С МАРКЕРОМ ====================
volatile bool ptt_physical_state = false;      // Реальное состояние педали
volatile bool ptt_tx_marker_active = false;    // Идет TX маркер
volatile bool ptt_rx_marker_active = false;    // Идет RX маркер
unsigned long ptt_marker_start = 0;             // Время начала маркера

// ==================== S-МЕТР НАСТРОЙКИ ====================
#define S_METER_SEGMENTS 16
#define S_METER_HEIGHT 20
#define S_METER_Y 45
#define S_METER_REFRESH_MS 50
#define S_METER_AVERAGING 8

const char* segment_names[] = {
  "S0", "S1", "S2", "S3", "S4", "S5", "S6", "S7", "S8", "S9",
  "+10", "+20", "+30", "+40", "+50", "+60"
};

#define SEGMENT_COLOR_GREEN 0x00FF00
#define SEGMENT_COLOR_RED 0xFF0000
#define TEXT_COLOR_GREEN 0x00FF00
#define TEXT_COLOR_RED 0xFF0000
#define TEXT_COLOR_BLACK 0x000000
#define TEXT_COLOR_WHITE 0xFFFFFF
#define PEAK_MARKER_COLOR 0xFFFFFF

volatile uint8_t s_meter_segments_active[S_METER_SEGMENTS] = {0};
int s_meter_peak_segment = -1;
float s_meter_voltage = 0.0;
float s_meter_filtered_voltage = 0.0;
int s_meter_value = 0;
int s_meter_display_value = 0;
unsigned long last_s_meter_update = 0;

// ==================== ТАБЛИЦА ДЕКОДЕРА ДИАПАЗОНОВ ====================
const uint8_t decoder_table[9] = {
  0b000, 0b001, 0b010, 0b011, 0b100, 0b101, 0b110, 0b111, 0b111
};

// ==================== ПРОТОТИПЫ ФУНКЦИЙ ====================
void buzzer_tone(int frequency_hz, int duration_ms);
