void load_all_settings();
int findCurrentBand(int32_t freq);
int findNextBandAbove(int32_t freq);
int findNextBandBelow(int32_t freq);
void toggleATT();
void togglePRE();
void changeStep(int direction);
void update_working_frequency();
void change_rit_offset(int delta);
void toggle_rit();
