void Alt_Thread(void *args);
void LCD_setup();
void show_splash_screen(const char* title, const char* subtitle);
bool check_menu_entry();
void update_band_decoder();
void ext_eeprom_init_bus();
void ext_eeprom_write_byte(uint16_t addr, uint8_t data);
uint8_t ext_eeprom_read_byte(uint16_t addr);
void ext_eeprom_write_word(uint16_t addr, uint16_t data);
uint16_t ext_eeprom_read_word(uint16_t addr);
void ext_eeprom_write_dword(uint16_t addr, uint32_t data);
uint32_t ext_eeprom_read_dword(uint16_t addr);
void ext_eeprom_write_float(uint16_t addr, float data);
float ext_eeprom_read_float(uint16_t addr);
void ext_eeprom_init();
void ext_eeprom_save_band_settings();
void ext_eeprom_load_band_frequency(int band, int32_t* base_frq_ptr, int32_t* Dial_frq_ptr);
void ext_eeprom_load_band_mode(int band, uint8_t* mode_ptr);
void ext_eeprom_save_common_settings();
void ext_eeprom_load_common_settings();
void ext_eeprom_save_all_defaults();
bool ext_eeprom_check_magic();
void manual_save_settings();
void auto_save_current_band();
void int_eeprom_init();
void int_eeprom_load_config();
void int_eeprom_save_config();

// ==================== ФУНКЦИЯ АВТОСОХРАНЕНИЯ ====================
void auto_save_current_band() {
  if (config.external_eeprom_enabled == 0) {
    Serial.println("External EEPROM disabled - nothing saved");
    return;
  }

  ext_eeprom_save_band_settings();
  ext_eeprom_save_common_settings();

  Serial.print("Auto-saved band: ");
  Serial.println(bands[current_band].name);
  Serial.print("Frequency: ");
  Serial.println(base_frq);
}

// ==================== ФУНКЦИЯ РУЧНОГО СОХРАНЕНИЯ ====================
void manual_save_settings() {
  if (config.external_eeprom_enabled == 0) {
    Serial.println("External EEPROM disabled - nothing saved");
    return;
  }
  ext_eeprom_save_band_settings();
  ext_eeprom_save_common_settings();
  Serial.println("Settings saved to external EEPROM (26/27)");
  buzzer_save(); // Звуковое подтверждение
}

// ==================== ФУНКЦИИ ВНЕШНЕЙ EEPROM (ОТДЕЛЬНАЯ ШИНА) ====================

void ext_eeprom_init_bus() {
  eepromWire.begin(EXT_EEPROM_SDA_PIN, EXT_EEPROM_SCL_PIN);
  eepromWire.setClock(400000);
  Serial.print("External EEPROM I2C bus initialized on pins SDA=");
  Serial.print(EXT_EEPROM_SDA_PIN);
  Serial.print(", SCL=");
  Serial.println(EXT_EEPROM_SCL_PIN);
}

void ext_eeprom_write_byte(uint16_t addr, uint8_t data) {
  if (config.external_eeprom_enabled == 0) return;
  eepromWire.beginTransmission(EXT_EEPROM_ADDR);
  eepromWire.write((addr >> 8) & 0xFF);
  eepromWire.write(addr & 0xFF);
  eepromWire.write(data);
  eepromWire.endTransmission();
  delay(5);
}

uint8_t ext_eeprom_read_byte(uint16_t addr) {
  if (config.external_eeprom_enabled == 0) return 0;
  eepromWire.beginTransmission(EXT_EEPROM_ADDR);
  eepromWire.write((addr >> 8) & 0xFF);
  eepromWire.write(addr & 0xFF);
  eepromWire.endTransmission();
  eepromWire.requestFrom(EXT_EEPROM_ADDR, 1);
  if (eepromWire.available()) return eepromWire.read();
  return 0;
}

void ext_eeprom_write_word(uint16_t addr, uint16_t data) {
  if (config.external_eeprom_enabled == 0) return;
  ext_eeprom_write_byte(addr, (data >> 8) & 0xFF);
  ext_eeprom_write_byte(addr + 1, data & 0xFF);
}

uint16_t ext_eeprom_read_word(uint16_t addr) {
  if (config.external_eeprom_enabled == 0) return 0;
  uint16_t data = 0;
  data = (ext_eeprom_read_byte(addr) << 8);
  data |= ext_eeprom_read_byte(addr + 1);
  return data;
}

void ext_eeprom_write_dword(uint16_t addr, uint32_t data) {
  if (config.external_eeprom_enabled == 0) return;
  ext_eeprom_write_byte(addr, (data >> 24) & 0xFF);
  ext_eeprom_write_byte(addr + 1, (data >> 16) & 0xFF);
  ext_eeprom_write_byte(addr + 2, (data >> 8) & 0xFF);
  ext_eeprom_write_byte(addr + 3, data & 0xFF);
}

uint32_t ext_eeprom_read_dword(uint16_t addr) {
  if (config.external_eeprom_enabled == 0) return 0;
  uint32_t data = 0;
  data = (uint32_t)ext_eeprom_read_byte(addr) << 24;
  data |= (uint32_t)ext_eeprom_read_byte(addr + 1) << 16;
  data |= (uint32_t)ext_eeprom_read_byte(addr + 2) << 8;
  data |= ext_eeprom_read_byte(addr + 3);
  return data;
}

void ext_eeprom_write_float(uint16_t addr, float data) {
  if (config.external_eeprom_enabled == 0) return;
  uint8_t *bytes = (uint8_t*)&data;
  for (int i = 0; i < 4; i++) ext_eeprom_write_byte(addr + i, bytes[i]);
}

float ext_eeprom_read_float(uint16_t addr) {
  if (config.external_eeprom_enabled == 0) return 0.0;
  float data;
  uint8_t *bytes = (uint8_t*)&data;
  for (int i = 0; i < 4; i++) bytes[i] = ext_eeprom_read_byte(addr + i);
  return data;
}

void ext_eeprom_init() {
  if (config.external_eeprom_enabled == 0) {
    Serial.println("External EEPROM disabled in config");
    return;
  }
  ext_eeprom_init_bus();
  eepromWire.beginTransmission(EXT_EEPROM_ADDR);
  if (eepromWire.endTransmission() != 0) {
    Serial.println("External EEPROM not found on dedicated I2C bus (26/27)! Disabling...");
    config.external_eeprom_enabled = 0;
    int_eeprom_save_config();
  } else {
    Serial.println("External EEPROM initialized on dedicated I2C bus (26/27)");
  }
}

void ext_eeprom_save_band_settings() {
  if (current_band < 0 || current_band >= NUM_BANDS) return;
  if (config.external_eeprom_enabled == 0) return;
  uint16_t band_freq_addr = EXT_EEPROM_BAND_FREQS_START + (current_band * 4);
  ext_eeprom_write_dword(band_freq_addr, base_frq);
  uint16_t band_mode_addr = EXT_EEPROM_BAND_MODES_START + current_band;
  ext_eeprom_write_byte(band_mode_addr, current_mode);
}

void ext_eeprom_load_band_frequency(int band, int32_t* base_frq_ptr, int32_t* Dial_frq_ptr) {
  if (band < 0 || band >= NUM_BANDS) {
    *base_frq_ptr = bands[band].center_freq;
    *Dial_frq_ptr = *base_frq_ptr;
    return;
  }
  if (config.external_eeprom_enabled == 0) {
    *base_frq_ptr = bands[band].center_freq;
    *Dial_frq_ptr = *base_frq_ptr;
    return;
  }
  uint16_t band_freq_addr = EXT_EEPROM_BAND_FREQS_START + (band * 4);
  uint32_t saved_freq = ext_eeprom_read_dword(band_freq_addr);
  if (saved_freq > 100000 && saved_freq >= bands[band].min_freq && saved_freq <= bands[band].max_freq) {
    *base_frq_ptr = (int32_t)saved_freq;
    *Dial_frq_ptr = *base_frq_ptr;
  } else {
    *base_frq_ptr = bands[band].center_freq;
    *Dial_frq_ptr = *base_frq_ptr;
    if (config.external_eeprom_enabled) ext_eeprom_write_dword(band_freq_addr, *base_frq_ptr);
  }
}

void ext_eeprom_load_band_mode(int band, uint8_t* mode_ptr) {
  if (band < 0 || band >= NUM_BANDS) {
    *mode_ptr = bands[band].mode;
    return;
  }
  if (config.external_eeprom_enabled == 0) {
    *mode_ptr = bands[band].mode;
    return;
  }
  uint16_t band_mode_addr = EXT_EEPROM_BAND_MODES_START + band;
  uint8_t saved_mode = ext_eeprom_read_byte(band_mode_addr);
  if (saved_mode == 0 || saved_mode == 1) *mode_ptr = saved_mode;
  else *mode_ptr = bands[band].mode;
}

void ext_eeprom_save_common_settings() {
  if (config.external_eeprom_enabled == 0) return;
  ext_eeprom_write_byte(EXT_EEPROM_BAND_ADDR, (current_band >= 0) ? current_band : 5);
  ext_eeprom_write_byte(EXT_EEPROM_ATT_ADDR, att_enabled ? 1 : 0);
  ext_eeprom_write_byte(EXT_EEPROM_PRE_ADDR, pre_enabled ? 1 : 0);
  ext_eeprom_write_byte(EXT_EEPROM_STEP_ADDR, current_step_index);
  ext_eeprom_write_word(EXT_EEPROM_RIT_OFFSET_ADDR, rit_offset);
  ext_eeprom_write_byte(EXT_EEPROM_RIT_ENABLED_ADDR, rit_enabled ? 1 : 0);
  ext_eeprom_write_dword(EXT_EEPROM_BASE_FREQ_ADDR, base_frq);
  ext_eeprom_write_dword(EXT_EEPROM_DIAL_FREQ_ADDR, Dial_frq);
  ext_eeprom_write_byte(EXT_EEPROM_PTT_STATE_ADDR, ptt_active ? 1 : 0);
  ext_eeprom_write_byte(EXT_EEPROM_ENABLED_ADDR, config.external_eeprom_enabled);
  ext_eeprom_write_byte(EXT_EEPROM_QUAD_MODE_ADDR, config.quadrature_mode);
}

void ext_eeprom_load_common_settings() {
  if (config.external_eeprom_enabled == 0) {
    current_band = 5; att_enabled = false; pre_enabled = false;
    current_step_index = 2; freq_step = steps[2];
    rit_offset = 0; rit_enabled = 0;
    base_frq = bands[5].center_freq; Dial_frq = base_frq;
    ptt_active = 0; config.quadrature_mode = 0;
    return;
  }
  if (!ext_eeprom_check_magic()) ext_eeprom_save_all_defaults();
  uint8_t saved_band = ext_eeprom_read_byte(EXT_EEPROM_BAND_ADDR);
  if (saved_band >= 0 && saved_band < NUM_BANDS) current_band = saved_band;
  else current_band = 5;
  att_enabled = (ext_eeprom_read_byte(EXT_EEPROM_ATT_ADDR) == 1);
  pre_enabled = (ext_eeprom_read_byte(EXT_EEPROM_PRE_ADDR) == 1);
  uint8_t saved_step = ext_eeprom_read_byte(EXT_EEPROM_STEP_ADDR);
  if (saved_step < NUM_STEPS) { current_step_index = saved_step; freq_step = steps[current_step_index]; }
  else { current_step_index = 2; freq_step = steps[2]; }
  rit_offset = (int16_t)ext_eeprom_read_word(EXT_EEPROM_RIT_OFFSET_ADDR);
  rit_enabled = ext_eeprom_read_byte(EXT_EEPROM_RIT_ENABLED_ADDR) == 1;
  base_frq = ext_eeprom_read_dword(EXT_EEPROM_BASE_FREQ_ADDR);
  Dial_frq = ext_eeprom_read_dword(EXT_EEPROM_DIAL_FREQ_ADDR);
  ptt_active = ext_eeprom_read_byte(EXT_EEPROM_PTT_STATE_ADDR) == 1;

  // ЗАГРУЖАЕМ QUAD MODE, НО НЕ ПРИМЕНЯЕМ СРАЗУ - ОН БУДЕТ ПЕРЕОПРЕДЕЛЕН ИЗ МЕНЮ
  uint8_t saved_quad_mode = ext_eeprom_read_byte(EXT_EEPROM_QUAD_MODE_ADDR);
  // НЕ применяем config.quadrature_mode = saved_quad_mode здесь!

  if (base_frq < min_frq || base_frq > max_frq) base_frq = bands[current_band].center_freq;
  if (Dial_frq < min_frq || Dial_frq > max_frq) Dial_frq = base_frq;
}

void ext_eeprom_save_all_defaults() {
  if (config.external_eeprom_enabled == 0) return;
  for (int i = 0; i < NUM_BANDS; i++) {
    uint16_t band_freq_addr = EXT_EEPROM_BAND_FREQS_START + (i * 4);
    ext_eeprom_write_dword(band_freq_addr, bands[i].center_freq);
    uint16_t band_mode_addr = EXT_EEPROM_BAND_MODES_START + i;
    ext_eeprom_write_byte(band_mode_addr, bands[i].mode);
  }
  ext_eeprom_write_byte(EXT_EEPROM_BAND_ADDR, 5);
  ext_eeprom_write_byte(EXT_EEPROM_ATT_ADDR, 0);
  ext_eeprom_write_byte(EXT_EEPROM_PRE_ADDR, 0);
  ext_eeprom_write_byte(EXT_EEPROM_STEP_ADDR, 2);
  ext_eeprom_write_word(EXT_EEPROM_RIT_OFFSET_ADDR, 0);
  ext_eeprom_write_byte(EXT_EEPROM_RIT_ENABLED_ADDR, 0);
  ext_eeprom_write_dword(EXT_EEPROM_BASE_FREQ_ADDR, bands[5].center_freq);
  ext_eeprom_write_dword(EXT_EEPROM_DIAL_FREQ_ADDR, bands[5].center_freq);
  ext_eeprom_write_byte(EXT_EEPROM_PTT_STATE_ADDR, 0);
  ext_eeprom_write_byte(EXT_EEPROM_ENABLED_ADDR, config.external_eeprom_enabled);
  ext_eeprom_write_byte(EXT_EEPROM_QUAD_MODE_ADDR, config.quadrature_mode);
  ext_eeprom_write_word(EXT_EEPROM_MAGIC_ADDR, EXT_EEPROM_MAGIC_VALUE);
}

bool ext_eeprom_check_magic() {
  if (config.external_eeprom_enabled == 0) return false;
  return (ext_eeprom_read_word(EXT_EEPROM_MAGIC_ADDR) == EXT_EEPROM_MAGIC_VALUE);
}

// ==================== ВНУТРЕННЯЯ EEPROM ФУНКЦИИ ====================
void int_eeprom_init() { EEPROM.begin(INT_EEPROM_SIZE); delay(10); }

void int_eeprom_load_config() {
  int_eeprom_init();
  uint16_t magic = EEPROM.read(INT_EEPROM_MAGIC_ADDR) | (EEPROM.read(INT_EEPROM_MAGIC_ADDR + 1) << 8);
  if (magic == INT_EEPROM_MAGIC_VALUE) {
    EEPROM.get(INT_EEPROM_CONFIG_ADDR, config);
    if (config.version == 4) {
      offset_frq_LSB = config.lsb_if_offset;
      offset_frq_USB = config.usb_if_offset;
      car_frq_LSB = config.lsb_bfo_freq;
      car_frq_USB = config.usb_bfo_freq;
      set_xtal_correction_hz(config.xtal_correction_hz);
    } else {
      config = ConfigSettings(); config.version = 4; config.quadrature_mode = 0;
      int_eeprom_save_config();
    }
  } else {
    config = ConfigSettings(); config.version = 4; config.quadrature_mode = 0;
    int_eeprom_save_config();
  }
  EEPROM.end();
}

void int_eeprom_save_config() {
  int_eeprom_init();
  EEPROM.write(INT_EEPROM_MAGIC_ADDR, INT_EEPROM_MAGIC_VALUE & 0xFF);
  EEPROM.write(INT_EEPROM_MAGIC_ADDR + 1, (INT_EEPROM_MAGIC_VALUE >> 8) & 0xFF);
  EEPROM.put(INT_EEPROM_CONFIG_ADDR, config);
  EEPROM.commit();
  EEPROM.end();
}

// ==================== ФУНКЦИЯ ОБНОВЛЕНИЯ ДЕКОДЕРА ====================
void update_band_decoder() {
  uint8_t decoder_code = decoder_table[current_band];
  digitalWrite(ADDR_A, (decoder_code >> 0) & 0x01);
  digitalWrite(ADDR_B, (decoder_code >> 1) & 0x01);
  digitalWrite(ADDR_C, (decoder_code >> 2) & 0x01);
}

// ==================== ФУНКЦИЯ ПРОВЕРКИ ВХОДА В МЕНЮ ====================
bool check_menu_entry() {
  delay(100);
  if (digitalRead(ENCODER_BUTTON_PIN) == LOW) {
    unsigned long start_time = millis();
    while (millis() - start_time < 3000) {
      if (digitalRead(ENCODER_BUTTON_PIN) == HIGH) return false;
      delay(10);
    }
    if (digitalRead(ENCODER_BUTTON_PIN) == LOW) return true;
  }
  return false;
}

// ==================== ИСПРАВЛЕННАЯ ЗАГРУЗКА ВСЕХ НАСТРОЕК ====================
void load_all_settings() {
  // Сначала загружаем из внутренней EEPROM (меню) - это главный приоритет
  int_eeprom_load_config();

  // Сохраняем значение quadrature_mode из меню
  uint8_t menu_quad_mode = config.quadrature_mode;
  uint8_t menu_ext_eeprom_enabled = config.external_eeprom_enabled;

  Serial.print("Menu quad mode: ");
  Serial.println(menu_quad_mode);

  if (config.external_eeprom_enabled) {
    ext_eeprom_init();
    if (ext_eeprom_check_magic()) {
      // Загружаем общие настройки из внешней EEPROM
      ext_eeprom_load_common_settings();

      // ВОССТАНАВЛИВАЕМ значение quadrature_mode из меню!
      config.quadrature_mode = menu_quad_mode;

      Serial.print("After ext load, restored quad mode to: ");
      Serial.println(config.quadrature_mode);

      // Загружаем частоту для текущего диапазона
      int32_t temp_base_frq = base_frq;
      int32_t temp_Dial_frq = Dial_frq;
      ext_eeprom_load_band_frequency(current_band, &temp_base_frq, &temp_Dial_frq);
      base_frq = temp_base_frq;
      Dial_frq = temp_Dial_frq;

      // Загружаем режим (LSB/USB) для текущего диапазона
      uint8_t temp_mode = current_mode;
      ext_eeprom_load_band_mode(current_band, &temp_mode);
      current_mode = temp_mode;

    } else {
      // Внешняя EEPROM пустая - сохраняем настройки по умолчанию
      ext_eeprom_save_all_defaults();
      current_band = 5;
      base_frq = bands[5].center_freq;
      Dial_frq = base_frq;
      current_mode = bands[5].mode;
      current_step_index = 2;
      freq_step = steps[2];
      att_enabled = false;
      pre_enabled = false;
      rit_offset = 0;
      rit_enabled = 0;
      ptt_active = 0;
    }
  } else {
    // Внешняя EEPROM отключена - используем значения по умолчанию
    current_band = 5;
    base_frq = bands[5].center_freq;
    Dial_frq = base_frq;
    current_mode = bands[5].mode;
    current_step_index = 2;
    freq_step = steps[2];
    att_enabled = false;
    pre_enabled = false;
    rit_offset = 0;
    rit_enabled = 0;
    ptt_active = 0;
  }

  // ЕЩЕ РАЗ гарантируем, что quad_mode из меню не перезаписан
  config.quadrature_mode = menu_quad_mode;
  config.external_eeprom_enabled = menu_ext_eeprom_enabled;

  si5351_init();
  update_working_frequency();
  f_fchange = 1; f_cchange = 1; f_mchange = 1; f_bchange = 1;
  set_xtal_correction_hz(config.xtal_correction_hz);

  Serial.println("=== Loaded Settings from EEPROM ===");
  Serial.print("Band: "); Serial.println(bands[current_band].name);
  Serial.print("Band index: "); Serial.println(current_band);
  Serial.print("Frequency: "); Serial.println(base_frq);
  Serial.print("Mode: "); Serial.println(current_mode == 0 ? "LSB" : "USB");
  Serial.print("Quad Mode: "); Serial.println(config.quadrature_mode);
  Serial.print("Ext EEPROM: "); Serial.println(config.external_eeprom_enabled);
  Serial.println("================================");
}

