void handle_menu() {
  static int last_encoder_menu_pos = 0;
  int current_pos = encoder.getPosition();

  if (current_pos != last_encoder_menu_pos) {
    if (!in_edit_mode) {
      int change = (current_pos > last_encoder_menu_pos) ? 1 : -1;
      menu_selection = (menu_selection + change + MENU_ITEMS_COUNT) % MENU_ITEMS_COUNT;
      menu_needs_redraw = true;
      if (calibration_mode_active && menu_selection != 0) {
        set_calibration_mode(false);
        calibration_mode_active = false;
      }
    } else {
      int change = (current_pos > last_encoder_menu_pos) ? 1 : -1;
      if (menu_selection == 0) {
        int32_t step;
        switch (edit_digit) {
          case 0: step = 1; break;
          case 1: step = 10; break;
          case 2: step = 100; break;
          case 3: step = 1000; break;
          case 4: if (change > 0) edit_value = -edit_value; break;
        }
        if (edit_digit < 4) edit_value += change * step;
        if (edit_value > 5000) edit_value = 5000;
        if (edit_value < -5000) edit_value = -5000;
        if (in_edit_mode) {
          set_xtal_correction_hz(edit_value);
          set_calibration_frequency_25mhz();
          show_edit_screen();
        }
      } else if (menu_selection == 5 || menu_selection == 6) {
        edit_float_value += change * 0.01;
        if (edit_float_value < 0.0) edit_float_value = 0.0;
        if (edit_float_value > 5.0) edit_float_value = 5.0;
        update_s_meter();
        show_edit_screen();
      } else if (menu_selection == 7) {
        edit_float_value += change * 0.05;
        if (edit_float_value < 0.0) edit_float_value = 0.0;
        if (edit_float_value > 1.0) edit_float_value = 1.0;
        show_edit_screen();
      } else if (menu_selection == 8 || menu_selection == 9) {
        if (change != 0) { edit_value = (edit_value == 1) ? 0 : 1; show_edit_screen(); }
      } else {
        int32_t step = 1;
        for (int i = 0; i < edit_digit; i++) step *= 10;
        edit_value += change * step;
        switch (menu_selection) {
          case 1: case 2: case 3: case 4:
            if (edit_value > 100000000) edit_value = 100000000;
            if (edit_value < 0) edit_value = 0;
            break;
        }
        show_edit_screen();
      }
    }
    last_encoder_menu_pos = current_pos;
  }

  static bool last_mode_state = HIGH;
  bool current_mode_state = digitalRead(MODE_BUTTON_PIN);

  if (current_mode_state == LOW && last_mode_state == HIGH) {
    buzzer_click();
    if (in_edit_mode) {
      if (menu_selection >= 5 && menu_selection <= 9) {
        in_edit_mode = false;
        menu_needs_redraw = true;
        show_menu();
      } else {
        edit_digit++;
        int max_digits = (menu_selection == 0) ? 5 : 7;
        if (edit_digit >= max_digits) edit_digit = 0;
        show_edit_screen();
      }
    } else {
      if (calibration_mode_active) { set_calibration_mode(false); calibration_mode_active = false; }
      set_xtal_correction_hz(config.xtal_correction_hz);
      in_menu_mode = false;
      lcd.fillScreen(TFT_BLACK);
      ESP.restart();
      return;
    }
    last_mode_state = LOW;
  } else if (current_mode_state == HIGH && last_mode_state == LOW) {
    last_mode_state = HIGH;
  }

  static bool last_encoder_button_state = HIGH;
  bool current_encoder_button_state = digitalRead(ENCODER_BUTTON_PIN);

  if (current_encoder_button_state == LOW && last_encoder_button_state == HIGH) {
    delay(50);
    if (current_encoder_button_state == LOW) {
      buzzer_click();
      if (!in_edit_mode) {
        if (menu_selection == MENU_ITEMS_COUNT - 2) {
          if (calibration_mode_active) { set_calibration_mode(false); calibration_mode_active = false; }
          int_eeprom_save_config();
          in_menu_mode = false;
          lcd.fillScreen(TFT_BLACK);
          ESP.restart();
          return;
        } else if (menu_selection == MENU_ITEMS_COUNT - 1) {
          if (calibration_mode_active) { set_calibration_mode(false); calibration_mode_active = false; }
          set_xtal_correction_hz(config.xtal_correction_hz);
          in_menu_mode = false;
          lcd.fillScreen(TFT_BLACK);
          ESP.restart();
          return;
        } else {
          in_edit_mode = true;
          edit_digit = 0;
          switch (menu_selection) {
            case 0: edit_value = config.xtal_correction_hz; calibration_mode_active = true; set_calibration_frequency_25mhz(); set_xtal_correction_hz(edit_value); break;
            case 1: edit_value = config.lsb_if_offset; break;
            case 2: edit_value = config.usb_if_offset; break;
            case 3: edit_value = config.lsb_bfo_freq; break;
            case 4: edit_value = config.usb_bfo_freq; break;
            case 5: edit_float_value = config.s_meter_min_voltage; break;
            case 6: edit_float_value = config.s_meter_max_voltage; break;
            case 7: edit_float_value = config.s_meter_smoothing; break;
            case 8: edit_value = config.external_eeprom_enabled; break;
            case 9: edit_value = config.quadrature_mode; break;
          }
          show_edit_screen();
        }
      } else {
        buzzer_save();
        switch (menu_selection) {
          case 0: config.xtal_correction_hz = edit_value; set_xtal_correction_hz(edit_value); break;
          case 1: config.lsb_if_offset = edit_value; break;
          case 2: config.usb_if_offset = edit_value; break;
          case 3: config.lsb_bfo_freq = edit_value; break;
          case 4: config.usb_bfo_freq = edit_value; break;
          case 5: config.s_meter_min_voltage = edit_float_value; break;
          case 6: config.s_meter_max_voltage = edit_float_value; break;
          case 7: config.s_meter_smoothing = edit_float_value; break;
          case 8: config.external_eeprom_enabled = edit_value; break;
          case 9: config.quadrature_mode = edit_value; break;
        }
        in_edit_mode = false;
        menu_needs_redraw = true;
        f_fchange = 1; f_cchange = 1;
      }
      last_encoder_button_state = LOW;
    }
  } else if (current_encoder_button_state == HIGH && last_encoder_button_state == LOW) {
    last_encoder_button_state = HIGH;
  }

  delay(10);
}

// ==================== ФУНКЦИИ УПРАВЛЕНИЯ ЧАСТОТОЙ ====================
void update_working_frequency() {
  if (rit_enabled && !ptt_active) Dial_frq = base_frq + rit_offset;
  else Dial_frq = base_frq;
  if (Dial_frq > max_frq) Dial_frq = max_frq;
  if (Dial_frq < min_frq) Dial_frq = min_frq;
  f_fchange = 1;
}

void change_rit_offset(int delta) {
  if (!rit_enabled || ptt_active) return;
  rit_offset += delta * RIT_STEP;
  if (rit_offset > rit_max_offset) rit_offset = rit_max_offset;
  if (rit_offset < -rit_max_offset) rit_offset = -rit_max_offset;
  update_working_frequency();
  f_dchange = 1;
}

void toggle_rit() {
  if (ptt_active) return;
  if (rit_enabled) {
    rit_enabled = 0; rit_offset = 0; Dial_frq = base_frq;
    f_fchange = 1; f_dchange = 1; update_working_frequency();
  } else {
    rit_enabled = 1; base_frq = Dial_frq; rit_offset = 0; f_dchange = 1;
  }
}

void reset_rit() {
  rit_enabled = 0; rit_offset = 0; Dial_frq = base_frq;
  f_fchange = 1; f_dchange = 1; update_working_frequency();
}

// ==================== ОБРАБОТКА PTT С МАРКЕРОМ ====================
void handle_ptt_change() {
  static unsigned long last_ptt_debounce = 0;
  unsigned long now = millis();

  if (now - last_ptt_debounce < 50) return;
  last_ptt_debounce = now;

  bool current_physical = (digitalRead(PTT_PIN) == LOW);

  if (current_physical == ptt_physical_state) return;

  ptt_physical_state = current_physical;

  if (ptt_physical_state) {
    if (!ptt_tx_marker_active && !ptt_rx_marker_active) {
      digitalWrite(PTT_OUT_PIN, HIGH);
      ptt_active = true;
      ptt_tx_marker_active = true;
      ptt_marker_start = now;
      buzzer_tx_marker();
    }
  } else {
    if (ptt_active) {
      ptt_active = false;
      ptt_rx_marker_active = true;
      ptt_marker_start = now;
      buzzer_tx_marker();
    }
  }
}

// ==================== ФУНКЦИЯ ОБНОВЛЕНИЯ SI5351 ====================
void update_si5351_frequencies() {
  if (f_fchange == 1) {
    uint32_t vfo_freq;
    if (config.quadrature_mode == 1) {
      vfo_freq = Dial_frq;
