// ==================== ФУНКЦИИ РАБОТЫ С ДИАПАЗОНАМИ ====================
int findCurrentBand(int32_t freq) {
  for (int i = 0; i < NUM_BANDS; i++) {
    if (freq >= bands[i].min_freq && freq <= bands[i].max_freq) return i;
  }
  return -1;
}

int findNextBandAbove(int32_t freq) {
  for (int i = 0; i < NUM_BANDS; i++) {
    if (bands[i].min_freq > freq) return i;
  }
  return NUM_BANDS - 1;
}

int findNextBandBelow(int32_t freq) {
  for (int i = NUM_BANDS - 1; i >= 0; i--) {
    if (bands[i].max_freq < freq) return i;
  }
  return 0;
}

void toggleATT() {
  if (ptt_active) return;
  att_enabled = !att_enabled;
  digitalWrite(ATT_PIN, att_enabled ? HIGH : LOW);
  f_attchange = 1; f_dchange = 1;
  buzzer_click();
}

void togglePRE() {
  if (ptt_active) return;
  pre_enabled = !pre_enabled;
  digitalWrite(PRE_PIN, pre_enabled ? HIGH : LOW);
  f_prechange = 1; f_dchange = 1;
  buzzer_click();
}

void changeStep(int direction) {
  if (ptt_active) return;
  static unsigned long last_change = 0;
  unsigned long now = millis();
  if (now - last_change < 100) return;
  last_change = now;

  int old_step = freq_step;
  current_step_index += direction;
  if (current_step_index < 0) current_step_index = NUM_STEPS - 1;
  else if (current_step_index >= NUM_STEPS) current_step_index = 0;
  freq_step = steps[current_step_index];

  MaxL = sqrt((MAX_Step - freq_step) / inv_Tacc);

  f_schange = 1; f_dchange = 1;

  if (freq_step != old_step) {
    base_frq = (base_frq / freq_step) * freq_step;
    update_working_frequency();
  }

  buzzer_click();
}

