// ==================== S-МЕТР ФУНКЦИИ ====================
void update_s_meter() {
  static uint16_t adc_buffer[S_METER_AVERAGING];
  static uint8_t adc_index = 0;
  static bool buffer_initialized = false;

  if (!buffer_initialized) {
    for (int i = 0; i < S_METER_AVERAGING; i++) adc_buffer[i] = analogRead(S_METER_ADC_PIN);
    buffer_initialized = true;
  }

  adc_buffer[adc_index] = analogRead(S_METER_ADC_PIN);
  adc_index = (adc_index + 1) % S_METER_AVERAGING;

  uint32_t adc_sum = 0;
  for (int i = 0; i < S_METER_AVERAGING; i++) adc_sum += adc_buffer[i];
  uint16_t adc_avg = adc_sum / S_METER_AVERAGING;

  s_meter_voltage = (adc_avg / 4095.0) * 3.3;

  static float voltage_filtered = 0;
  static bool first_measurement = true;
  if (first_measurement) { voltage_filtered = s_meter_voltage; first_measurement = false; }

  static float last_alpha = -1;
  static float one_minus_alpha = 0.7;
  float alpha = config.s_meter_smoothing;

  if (alpha != last_alpha) {
    if (alpha < 0.01) alpha = 0.01;
    if (alpha > 0.99) alpha = 0.99;
    one_minus_alpha = 1.0 - alpha;
    last_alpha = alpha;
  }

  voltage_filtered = voltage_filtered * one_minus_alpha + s_meter_voltage * alpha;
  s_meter_filtered_voltage = voltage_filtered;

  if (config.s_meter_max_voltage <= config.s_meter_min_voltage) {
    s_meter_value = (s_meter_filtered_voltage >= 3.2) ? 60 : 0;
  } else {
    float range = config.s_meter_max_voltage - config.s_meter_min_voltage;
    if (s_meter_filtered_voltage <= config.s_meter_min_voltage) s_meter_value = 0;
    else if (s_meter_filtered_voltage >= config.s_meter_max_voltage) s_meter_value = 60;
    else {
      float normalized = (s_meter_filtered_voltage - config.s_meter_min_voltage) / range;
      s_meter_value = (int)(normalized * 60.0f);
    }
  }

  if (s_meter_value < 0) s_meter_value = 0;
  if (s_meter_value > 60) s_meter_value = 60;

  s_meter_display_value = s_meter_value;

  for (int i = 0; i < S_METER_SEGMENTS; i++) {
    if (i < 10) s_meter_segments_active[i] = (s_meter_display_value >= i) ? 1 : 0;
    else {
      int threshold = 10 + (i - 10) * 10;
      s_meter_segments_active[i] = (s_meter_display_value >= threshold) ? 1 : 0;
    }
  }

  static int s_meter_peak = 0;
  static unsigned long last_peak_update = 0;
  unsigned long current_time = millis();

  if (s_meter_value > s_meter_peak) { s_meter_peak = s_meter_value; last_peak_update = current_time; }
  if (current_time - last_peak_update > 3000) s_meter_peak = s_meter_value;

  s_meter_peak_segment = -1;
  if (s_meter_peak < 10) s_meter_peak_segment = s_meter_peak;
  else {
    int peak_plus = (s_meter_peak - 10) / 10;
    if (peak_plus < (S_METER_SEGMENTS - 10)) s_meter_peak_segment = 10 + peak_plus;
  }
}

void draw_s_meter(int yoff) {
  unsigned long now = millis();
  if (now - last_s_meter_update > S_METER_REFRESH_MS) { update_s_meter(); last_s_meter_update = now; }

  int screen_width = lcd.width();
  int segment_width = screen_width / S_METER_SEGMENTS;

  for (int i = 0; i < S_METER_SEGMENTS; i++) {
    int x1 = i * segment_width;
    int y1 = S_METER_Y - yoff;

    uint32_t segment_color, text_color;
    bool is_active = s_meter_segments_active[i];
    bool is_peak = (i == s_meter_peak_segment);

    if (i < 10) {
      if (is_active) { segment_color = SEGMENT_COLOR_GREEN; text_color = TEXT_COLOR_BLACK; }
      else { segment_color = BGCol; text_color = TEXT_COLOR_GREEN; }
    } else {
      if (is_active) { segment_color = SEGMENT_COLOR_RED; text_color = TEXT_COLOR_WHITE; }
      else { segment_color = BGCol; text_color = TEXT_COLOR_RED; }
    }

    sprites[flip].fillRect(x1, y1, segment_width, S_METER_HEIGHT, segment_color);
    sprites[flip].drawRect(x1, y1, segment_width, S_METER_HEIGHT, 0x333333);

    if (is_peak && is_active) sprites[flip].drawRect(x1, y1, segment_width, S_METER_HEIGHT, PEAK_MARKER_COLOR);

    sprites[flip].setFont(&fonts::Font0);
    sprites[flip].setTextColor(text_color);

    const char* label = segment_names[i];
    int text_width = strlen(label) * 6;
    int text_x = x1 + (segment_width - text_width) / 2;
    int text_y = y1 + (S_METER_HEIGHT / 2);

    sprites[flip].setCursor(text_x, text_y);
    sprites[flip].print(label);
  }
}

// ==================== ФУНКЦИИ БИПЕРА ====================
void buzzer_tone(int frequency_hz, int duration_ms) {
  if (duration_ms == 0) return;
  int period_us = 1000000 / frequency_hz;
  int half_period_us = period_us / 2;
  unsigned long start_time = millis();
  while (millis() - start_time < (unsigned long)duration_ms) {
    digitalWrite(BUZZER_PIN, HIGH);
    delayMicroseconds(half_period_us);
    digitalWrite(BUZZER_PIN, LOW);
    delayMicroseconds(half_period_us);
  }
}

void buzzer_click() { buzzer_tone(2500, CLICK_DURATION); }
void buzzer_long() { buzzer_tone(1500, LONG_DURATION); }
void buzzer_save() { buzzer_tone(2000, 80); delay(30); buzzer_tone(2500, 80); delay(30); buzzer_tone(3000, 150); }
void buzzer_mode_change() { buzzer_tone(2200, 40); delay(20); buzzer_tone(2800, 40); }
void buzzer_band_change() { buzzer_tone(2000, 60); delay(30); buzzer_tone(2000, 60); }
void buzzer_tx_marker() { buzzer_tone(TX_MARKER_FREQ, TX_MARKER_DURATION); }

// ==================== ВТОРОЙ ПОТОК ====================
void Alt_Thread(void *args) {
  Serial.println("Alt_Thread started on core 0");

  pinMode(S_METER_ADC_PIN, INPUT);
  analogReadResolution(12);
  analogSetAttenuation(ADC_11db);

  is_in_band = (findCurrentBand(Dial_frq) == current_band);

  digitalWrite(ATT_PIN, att_enabled ? HIGH : LOW);
  digitalWrite(PRE_PIN, pre_enabled ? HIGH : LOW);
  digitalWrite(PTT_OUT_PIN, LOW);

  pinMode(ADDR_A, OUTPUT);
  pinMode(ADDR_B, OUTPUT);
  pinMode(ADDR_C, OUTPUT);

  update_band_decoder();

  pinMode(RIT_PIN, INPUT_PULLUP);
  pinMode(PTT_PIN, INPUT_PULLUP);
  pinMode(PTT_OUT_PIN, OUTPUT);

  pinMode(BAND_UP_PIN, INPUT);
  pinMode(BAND_DOWN_PIN, INPUT);
  pinMode(EEPROM_BUTTON_PIN, INPUT); // GPIO35 - без внутренней подтяжки!
  pinMode(BUZZER_PIN, OUTPUT);
  digitalWrite(BUZZER_PIN, LOW);

  unsigned long startup_protection_end = millis() + 2000;
  static unsigned long last_encoder_check = 0;
  static unsigned long last_button_check = 0;

  while (1) {
    unsigned long current_time = millis();
    bool startup_protection = current_time < startup_protection_end;

    // ===== ОБРАБОТКА МАРКЕРОВ PTT =====
    if (ptt_tx_marker_active) {
      if (current_time - ptt_marker_start >= TX_MARKER_DURATION) {
        ptt_tx_marker_active = false;
      }
    }

    if (ptt_rx_marker_active) {
      if (current_time - ptt_marker_start >= TX_MARKER_DURATION) {
        ptt_rx_marker_active = false;
        digitalWrite(PTT_OUT_PIN, LOW);
      }
    }

    if (!in_menu_mode) {
      if (current_time - last_encoder_check > 2) {
        encoder.tick();
        int newPos = encoder.getPosition();

        if (newPos != last_encoder_pos) {
          int direction = (int)encoder.getDirection();
          if (direction != 0) {
            if (ptt_active || ptt_tx_marker_active || ptt_rx_marker_active) {
              base_frq += direction * freq_step;
              if (base_frq > max_frq) base_frq = max_frq;
              if (base_frq < min_frq) base_frq = min_frq;
              update_working_frequency();
              f_dchange = 1; f_fchange = 1;
            } else {
              if (rit_enabled) change_rit_offset(direction);
              else {
                base_frq += direction * freq_step;
                if (base_frq > max_frq) base_frq = max_frq;
                if (base_frq < min_frq) base_frq = min_frq;
                update_working_frequency();
                f_fchange = 1;

                int band_index = findCurrentBand(Dial_frq);
                if (band_index != -1) {
                  if (!is_in_band || current_band != band_index) {
                    auto_save_current_band();

                    current_band = band_index;
                    is_in_band = true;
                    f_bchange = 1; f_dchange = 1;
                    if (current_mode != bands[current_band].mode) {
                      current_mode = bands[current_band].mode;
                      f_mchange = 1; f_cchange = 1;
                      buzzer_mode_change();
                    }
                  }
                } else { if (is_in_band) { is_in_band = false; f_bchange = 1; f_dchange = 1; } }
              }
            }
            last_encoder_pos = newPos;
          }
        }
        last_encoder_check = current_time;
      }
    }

    if (current_time - last_button_check > 10) {
      last_button_check = current_time;

      update_band_decoder();

      if (mode_button_pressed) {
        mode_button_pressed = false;
        if (!startup_protection && !ptt_active && !ptt_tx_marker_active && !ptt_rx_marker_active && !in_menu_mode) {
          reset_rit();
          current_mode = !current_mode;
          f_mchange = 1; f_cchange = 1; f_dchange = 1; f_fchange = 1;
          buzzer_mode_change();
        }
      }

      bool band_up_current = digitalRead(BAND_UP_PIN) == LOW;
      bool band_down_current = digitalRead(BAND_DOWN_PIN) == LOW;
      bool encoder_button_current = digitalRead(ENCODER_BUTTON_PIN) == LOW;
      bool eeprom_button_current = digitalRead(EEPROM_BUTTON_PIN) == LOW;
      bool rit_button_current = digitalRead(RIT_PIN) == LOW;

      handle_ptt_change();

      if (rit_button_current && !startup_protection && !ptt_active && !ptt_tx_marker_active && !ptt_rx_marker_active && !in_menu_mode) {
        if (!rit_button_pressed) rit_button_pressed = true;
      } else {
        if (rit_button_pressed && !startup_protection && !ptt_active && !ptt_tx_marker_active && !ptt_rx_marker_active && !in_menu_mode) {
          toggle_rit();
          rit_button_pressed = false;
          f_fchange = 1;
          buzzer_click();
        }
      }

      // ===== КНОПКА СОХРАНЕНИЯ GPIO35 (ТОЛЬКО СОХРАНЕНИЕ) =====
      if (eeprom_button_current && !startup_protection && !in_menu_mode) {
        if (!eeprom_button_pressed) {
          eeprom_button_pressed = true;
          buzzer_click(); // Короткий клик при нажатии
        }
      } else {
        if (eeprom_button_pressed && !startup_protection && !in_menu_mode) {
          manual_save_settings(); // Только сохранение, без очистки
          eeprom_button_pressed = false;
        }
      }

      if (band_up_current && !startup_protection && !ptt_active && !ptt_tx_marker_active && !ptt_rx_marker_active && !in_menu_mode) {
        if (!band_up_pressed) {
          band_up_pressed = true;
          band_up_press_start = current_time;
          band_up_long_press_active = false;
        } else {
          unsigned long press_duration = current_time - band_up_press_start;
          if (press_duration >= STEP_CHANGE_DELAY && !band_up_long_press_active) {
            changeStep(1);
            band_up_long_press_active = true;
          }
        }
      } else {
        if (band_up_pressed && !startup_protection && !ptt_active && !ptt_tx_marker_active && !ptt_rx_marker_active && !in_menu_mode) {
          unsigned long press_duration = current_time - band_up_press_start;
          if (press_duration < STEP_CHANGE_DELAY && !band_up_long_press_active) {

            auto_save_current_band();

            reset_rit();
            int new_band;
            if (!is_in_band) new_band = findNextBandAbove(Dial_frq);
            else {
              new_band = current_band + 1;
              if (new_band >= NUM_BANDS) new_band = 0;
            }

            current_band = new_band;

            int32_t new_base_frq = base_frq;
            int32_t new_Dial_frq = Dial_frq;
            uint8_t new_mode = current_mode;
            ext_eeprom_load_band_frequency(current_band, &new_base_frq, &new_Dial_frq);
            ext_eeprom_load_band_mode(current_band, &new_mode);
            base_frq = new_base_frq;
            Dial_frq = new_Dial_frq;
            current_mode = new_mode;

            is_in_band = true;
            f_mchange = 1; f_fchange = 1; f_bchange = 1; f_dchange = 1; f_cchange = 1;

            update_working_frequency();
            update_si5351_frequencies();

            buzzer_band_change();
          }
          band_up_pressed = false;
          band_up_long_press_active = false;
        }
      }

      if (band_down_current && !startup_protection && !ptt_active && !ptt_tx_marker_active && !ptt_rx_marker_active && !in_menu_mode) {
        if (!band_down_pressed) {
          band_down_pressed = true;
          band_down_press_start = current_time;
          band_down_long_press_active = false;
        } else {
          unsigned long press_duration = current_time - band_down_press_start;
          if (press_duration >= STEP_CHANGE_DELAY && !band_down_long_press_active) {
            changeStep(-1);
            band_down_long_press_active = true;
          }
        }
      } else {
        if (band_down_pressed && !startup_protection && !ptt_active && !ptt_tx_marker_active && !ptt_rx_marker_active && !in_menu_mode) {
          unsigned long press_duration = current_time - band_down_press_start;
          if (press_duration < STEP_CHANGE_DELAY && !band_down_long_press_active) {

            auto_save_current_band();

            reset_rit();
            int new_band;
            if (!is_in_band) new_band = findNextBandBelow(Dial_frq);
            else {
              new_band = current_band - 1;
              if (new_band < 0) new_band = NUM_BANDS - 1;
            }

            current_band = new_band;

            int32_t new_base_frq = base_frq;
            int32_t new_Dial_frq = Dial_frq;
            uint8_t new_mode = current_mode;
            ext_eeprom_load_band_frequency(current_band, &new_base_frq, &new_Dial_frq);
            ext_eeprom_load_band_mode(current_band, &new_mode);
            base_frq = new_base_frq;
            Dial_frq = new_Dial_frq;
            current_mode = new_mode;

            is_in_band = true;
            f_mchange = 1; f_fchange = 1; f_bchange = 1; f_dchange = 1; f_cchange = 1;

            update_working_frequency();
            update_si5351_frequencies();

            buzzer_band_change();
          }
          band_down_pressed = false;
          band_down_long_press_active = false;
        }
      }

      if (encoder_button_current && !startup_protection && !ptt_active && !ptt_tx_marker_active && !ptt_rx_marker_active && !in_menu_mode) {
        if (!encoder_button_pressed) {
          encoder_button_pressed = true;
          encoder_button_press_start = current_time;
          encoder_button_long_press_active = false;
          buzzer_click();
        } else {
          unsigned long press_duration = current_time - encoder_button_press_start;
          if (press_duration >= ATT_PRE_CHANGE_DELAY && !encoder_button_long_press_active) {
            togglePRE();
            encoder_button_long_press_active = true;
          }
        }
      } else {
        if (encoder_button_pressed && !startup_protection && !ptt_active && !ptt_tx_marker_active && !ptt_rx_marker_active && !in_menu_mode) {
          unsigned long press_duration = current_time - encoder_button_press_start;
          if (press_duration < ATT_PRE_CHANGE_DELAY && !encoder_button_long_press_active) toggleATT();
          encoder_button_pressed = false;
          encoder_button_long_press_active = false;
        }
      }
    }

    if (!in_menu_mode) update_si5351_frequencies();

    delay(2);
  }
}

// ==================== ОСНОВНАЯ ПРОГРАММА ====================
void setup(void) {
  Serial.begin(115200);
  delay(1000);
  Serial.println("\n\n=== Meander SSB Transceiver v2.44 Fixed Quad Mode ===");
  Serial.println("Starting system with separated I2C buses...");
  Serial.println("SI5351: Standard I2C bus (SDA=21, SCL=22)");
  Serial.println("EEPROM: Dedicated I2C bus (SDA=26, SCL=27)");
  Serial.println("Buzzer: GPIO1 - 1kHz TX marker and button clicks");
  Serial.println("EEPROM Button: GPIO35 - short press saves settings (no erase)");
  Serial.println("FIX: Menu settings now have priority over EEPROM");

  pinMode(BUZZER_PIN, OUTPUT);
  digitalWrite(BUZZER_PIN, LOW);

  in_menu_mode = check_menu_entry();

  pinMode(MODE_BUTTON_PIN, INPUT_PULLUP);
  attachInterrupt(digitalPinToInterrupt(MODE_BUTTON_PIN), modeButtonISR, FALLING);

  pinMode(ENCODER_BUTTON_PIN, INPUT_PULLUP);
  pinMode(BAND_UP_PIN, INPUT);
  pinMode(BAND_DOWN_PIN, INPUT);
  pinMode(EEPROM_BUTTON_PIN, INPUT); // GPIO35 - только вход, без подтяжки!
  pinMode(RIT_PIN, INPUT_PULLUP);
  pinMode(PTT_PIN, INPUT_PULLUP);
  pinMode(PTT_OUT_PIN, OUTPUT);

  pinMode(ATT_PIN, OUTPUT);
  pinMode(PRE_PIN, OUTPUT);
  digitalWrite(ATT_PIN, LOW);
  digitalWrite(PRE_PIN, LOW);
  digitalWrite(PTT_OUT_PIN, LOW);

  pinMode(ENCODER_PIN_A, INPUT_PULLUP);
  pinMode(ENCODER_PIN_B, INPUT_PULLUP);
  attachInterrupt(digitalPinToInterrupt(ENCODER_PIN_A), encoderISR, CHANGE);
  attachInterrupt(digitalPinToInterrupt(ENCODER_PIN_B), encoderISR, CHANGE);

  LCD_setup();

  if (!in_menu_mode) {
    load_all_settings();

    xTaskCreatePinnedToCore(Alt_Thread, "Alt_Thread", 8192, NULL, 4, &H_Task, 0);
    task_created = true;

    show_splash_screen("Hello", "Meander SSB");

    update_si5351_frequencies();

  } else {
    si5351_init();
    int_eeprom_load_config();
    set_calibration_frequency_25mhz();
    calibration_mode_active = true;

    menu_needs_redraw = true;
  }
}

// ==================== ГЛАВНЫЙ ЦИКЛ ====================
void loop(void) {
  static unsigned long last_display_update = 0;
  unsigned long current_time = millis();

  if (in_menu_mode) {
    if (menu_needs_redraw) show_menu();
    handle_menu();
  } else {
    if (current_time - last_display_update > 33) {
      last_display_update = current_time;

      int32_t Disp_frq = Dial_frq;

      for (int yoff = 0; yoff < lcd.height(); yoff += sprite_height) {
        sprites[flip].clear(BGCol);

        dial.draw(Disp_frq, yoff);
        draw_s_meter(yoff);                      // для отключения S-Метра закомментировать эту строку.

        int xdf = -2, ydf = 0;
        char str[12];
        sprintf(str, "%03d.%03d.%02d",
                Disp_frq / 1000000, (Disp_frq % 1000000) / 1000, (Disp_frq % 1000) / 10);
        for (int i = 0; i < 12; i++) {
          switch (str[i]) {
            case '0':
              if ((i == 0) || (i == 1 && str[0] == '0'))
                sprites[flip].pushImage(xdf, ydf - yoff, nxfontWidth, nxfontHeight, nxb);
              else
                sprites[flip].pushImage(xdf, ydf - yoff, nxfontWidth, nxfontHeight, nx0);
              xdf += nxfontWidth;
              break;
            case '1': sprites[flip].pushImage(xdf, ydf - yoff, nxfontWidth, nxfontHeight, nx1); xdf += nxfontWidth; break;
            case '2': sprites[flip].pushImage(xdf, ydf - yoff, nxfontWidth, nxfontHeight, nx2); xdf += nxfontWidth; break;
            case '3': sprites[flip].pushImage(xdf, ydf - yoff, nxfontWidth, nxfontHeight, nx3); xdf += nxfontWidth; break;
            case '4': sprites[flip].pushImage(xdf, ydf - yoff, nxfontWidth, nxfontHeight, nx4); xdf += nxfontWidth; break;
            case '5': sprites[flip].pushImage(xdf, ydf - yoff, nxfontWidth, nxfontHeight, nx5); xdf += nxfontWidth; break;
            case '6': sprites[flip].pushImage(xdf, ydf - yoff, nxfontWidth, nxfontHeight, nx6); xdf += nxfontWidth; break;
            case '7': sprites[flip].pushImage(xdf, ydf - yoff, nxfontWidth, nxfontHeight, nx7); xdf += nxfontWidth; break;
            case '8': sprites[flip].pushImage(xdf, ydf - yoff, nxfontWidth, nxfontHeight, nx8); xdf += nxfontWidth; break;
            case '9': sprites[flip].pushImage(xdf, ydf - yoff, nxfontWidth, nxfontHeight, nx9); xdf += nxfontWidth; break;
            case '.': sprites[flip].pushImage(xdf, ydf - yoff, nxfontWidth, nxfontHeight, nxd); xdf += nxfontWidth; break;
          }
        }

        int mode_x = 1;
        int mode_y = 70;

        if (config.quadrature_mode == 1) {
            sprites[flip].setFont(&fonts::Font2);
            sprites[flip].setTextColor(TFT_WHITE, BGCol);
            sprites[flip].setCursor(mode_x, mode_y - yoff);
            sprites[flip].print("Q");
        } else {
            uint32_t mode_color;
            if (ptt_active || ptt_tx_marker_active || ptt_rx_marker_active) mode_color = TFT_DARKGREY;
            else mode_color = 0xFFFFFF;
            sprites[flip].setFont(&fonts::Font2);
            sprites[flip].setTextColor(mode_color, BGCol);
            sprites[flip].setCursor(mode_x, mode_y - yoff);
            sprites[flip].print(current_mode == 0 ? "LSB" : "USB");
        }

        int ptt_display_x = 288;
        int ptt_display_y = 87;
        sprites[flip].setFont(&fonts::Font2);
        if (ptt_active || ptt_tx_marker_active || ptt_rx_marker_active) {
          sprites[flip].setTextColor(TFT_YELLOW, BGCol);
          sprites[flip].setCursor(ptt_display_x, ptt_display_y - yoff);
          sprites[flip].print("TX");
        } else {
          sprites[flip].setTextColor(TFT_GREEN, BGCol);
          sprites[flip].setCursor(ptt_display_x, ptt_display_y - yoff);
          sprites[flip].print("RX");
        }

        int band_x = 1;
        int band_y = 10;
        sprites[flip].setFont(&fonts::Font2);
        if (rit_enabled && !ptt_active && !ptt_tx_marker_active && !ptt_rx_marker_active) {
          sprites[flip].setTextColor(TFT_RED, BGCol);
          sprites[flip].setCursor(band_x, band_y - yoff);
          sprites[flip].print("RIT");
        } else {
          uint32_t band_color = (ptt_active || ptt_tx_marker_active || ptt_rx_marker_active) ? TFT_DARKGREY : (is_in_band ? TFT_YELLOW : TFT_RED);
          sprites[flip].setTextColor(band_color, BGCol);
          sprites[flip].setCursor(band_x, band_y - yoff);
          sprites[flip].print(is_in_band ? bands[current_band].name : "--");
        }

        int step_x = 280;
        int step_y = 70;
        sprites[flip].setFont(&fonts::Font2);

        if (!ptt_active && !ptt_tx_marker_active && !ptt_rx_marker_active && rit_enabled) {
          char rit_str[10];
          if (rit_offset > 0) sprintf(rit_str, "+%d", rit_offset);
          else if (rit_offset < 0) sprintf(rit_str, "%d", rit_offset);
          else sprintf(rit_str, "0");
          sprites[flip].setTextColor(0x00FF00, BGCol);
          sprites[flip].setCursor(step_x, step_y - yoff);
          sprites[flip].print(rit_str);
        } else {
          uint16_t step_color;
          switch (freq_step) {
            case 10: step_color = TFT_CYAN; break;
            case 100: step_color = TFT_GREEN; break;
            case 1000: step_color = TFT_YELLOW; break;
            case 10000: step_color = TFT_ORANGE; break;
            case 100000: step_color = TFT_RED; break;
            default: step_color = TFT_WHITE;
          }
          sprites[flip].setTextColor(step_color, BGCol);
          sprites[flip].setCursor(step_x, step_y - yoff);
          char step_str[10];
          if (freq_step < 1000) sprintf(step_str, "S%d", freq_step);
          else if (freq_step < 1000000) sprintf(step_str, "S%dk", freq_step / 1000);
          sprites[flip].print(step_str);
        }

        int att_x = 1;
        int att_y = 85;
        int pre_x = 1;
        int pre_y = 100;

        sprites[flip].setFont(&fonts::Font2);

        if (ptt_active || ptt_tx_marker_active || ptt_rx_marker_active) sprites[flip].setTextColor(TFT_DARKGREY, BGCol);
        else sprites[flip].setTextColor(att_enabled ? TFT_YELLOW : TFT_DARKGREY, BGCol);
        sprites[flip].setCursor(att_x, att_y - yoff);
        sprites[flip].print("ATT");

        if (ptt_active || ptt_tx_marker_active || ptt_rx_marker_active) sprites[flip].setTextColor(TFT_DARKGREY, BGCol);
        else sprites[flip].setTextColor(pre_enabled ? TFT_YELLOW : TFT_DARKGREY, BGCol);
        sprites[flip].setCursor(pre_x, pre_y - yoff);
        sprites[flip].print("PRE");

        sprites[flip].pushSprite(&lcd, 0, yoff);
        flip = !flip;
      }
    }
  }

  delay(1);
}
